// Whether Peal's reads of the ad network work: `reconnectNeeded` once the network refused the sign-in's token, until its person signs in again.
type AdAccess string

const (
	AdAccessWorking         AdAccess = "working"
	AdAccessReconnectNeeded AdAccess = "reconnectNeeded"
)

func NewAdAccessFromString(s string) (AdAccess, error) {
	switch s {
	case "working":
		return AdAccessWorking, nil
	case "reconnectNeeded":
		return AdAccessReconnectNeeded, nil
	}
	var t AdAccess
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

func (a AdAccess) Ptr() *AdAccess {
	return &a
}

