// What the advertiser declares the ad is about. Peal boosts `none` only: an ad about housing, employment, financial products and services, or social issues, elections or politics is refused, as each restricts targeting in ways Peal does not handle.
type SpecialAdCategory string

const (
	SpecialAdCategoryNone                      SpecialAdCategory = "none"
	SpecialAdCategoryHousing                   SpecialAdCategory = "housing"
	SpecialAdCategoryEmployment                SpecialAdCategory = "employment"
	SpecialAdCategoryFinancialProductsServices SpecialAdCategory = "financialProductsServices"
	SpecialAdCategoryIssuesElectionsPolitics   SpecialAdCategory = "issuesElectionsPolitics"
)

func NewSpecialAdCategoryFromString(s string) (SpecialAdCategory, error) {
	switch s {
	case "none":
		return SpecialAdCategoryNone, nil
	case "housing":
		return SpecialAdCategoryHousing, nil
	case "employment":
		return SpecialAdCategoryEmployment, nil
	case "financialProductsServices":
		return SpecialAdCategoryFinancialProductsServices, nil
	case "issuesElectionsPolitics":
		return SpecialAdCategoryIssuesElectionsPolitics, nil
	}
	var t SpecialAdCategory
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

func (s SpecialAdCategory) Ptr() *SpecialAdCategory {
	return &s
}
